import * as THREE from 'three';
import { GAME_CONFIG } from './config/GameConfig';
import { resolveCourseSelection } from './courses';
import { parseLaunchOptions } from './dev/LaunchOptions';
import { InputManager } from './input';
import './style.css';
import { AppUI } from './ui';

const root=document.querySelector<HTMLDivElement>('#app');
if(!root)throw new Error('Missing #app bootstrap element');
document.title=GAME_CONFIG.title;
const launch=parseLaunchOptions(window.location.search);
const selection=resolveCourseSelection(launch);
document.documentElement.dataset.course=selection.course.id;
document.documentElement.dataset.hole=String(selection.holeNumber);
const renderer=new THREE.WebGLRenderer({antialias:true});
renderer.setPixelRatio(Math.min(window.devicePixelRatio,2));
renderer.setSize(window.innerWidth,window.innerHeight);root.append(renderer.domElement);
const uiRoot=document.createElement('div');uiRoot.className='cpa-layer';root.append(uiRoot);new AppUI(uiRoot,{},{initialCourseId:selection.course.id});
const scene=new THREE.Scene();
const camera=new THREE.PerspectiveCamera(60,window.innerWidth/window.innerHeight,.1,100);camera.position.set(0,2,5);
const input=new InputManager({pointerTarget:renderer.domElement});
let diagnostics:{frame():void;dispose():void}|undefined;
if(launch.debug)void import('./dev').then(({DeveloperDiagnostics})=>{document.documentElement.dataset.debug='1';diagnostics=new DeveloperDiagnostics({root,renderer,scene,camera})});
const resize=()=>{camera.aspect=window.innerWidth/window.innerHeight;camera.updateProjectionMatrix();renderer.setSize(window.innerWidth,window.innerHeight)};
window.addEventListener('resize',resize);
renderer.setAnimationLoop(()=>{renderer.render(scene,camera);diagnostics?.frame();input.endFrame()});
window.addEventListener('pagehide',()=>{input.dispose();diagnostics?.dispose()},{once:true});
EOF
